// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint96 balance) public {
        uint96 startBal = uint96(bound(uint256(balance), 1, type(uint96).max));
        address recipient = makeAddr("recipient");
        vm.deal(address(c), startBal);
        uint256 balBefore = recipient.balance;
        vm.prank(address(this));
        c.withdrawAll(recipient);
        uint256 balAfter = recipient.balance;
        assertTrue(balAfter - balBefore == startBal);
    }
}
